import React, { useRef, useState } from 'react';

interface SimulationControlsProps {
  currentPhase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape';
  onAdvancePhase: (phase: 'norton' | 'microsoft' | 'google' | 'malwarebytes' | 'generic' | 'advanced' | 'extreme' | 'escape') => void;
  onLearnMore: () => void;
  onReset: () => void;
  nortonEscalation?: boolean; // Norton escalation state
  nortonMuted?: boolean; // Norton speech muted state
}

const SimulationControls: React.FC<SimulationControlsProps> = ({
  currentPhase,
  onAdvancePhase,
  onLearnMore,
  onReset,
  nortonEscalation = false, // Norton escalation state
  nortonMuted = false // Norton speech muted state
}) => {

  const phases = [
    { id: 'norton', name: 'Norton', color: '#ff6b35' },
    { id: 'microsoft', name: 'Microsoft', color: '#0078d4' },
    { id: 'google', name: 'Google', color: '#4285f4' },
    { id: 'malwarebytes', name: 'Malwarebytes', color: '#00a651' },
    { id: 'generic', name: 'Legal Threats', color: '#ff0000' },
    { id: 'advanced', name: 'Tech Support', color: '#8b0000' },
    { id: 'extreme', name: 'Ransomware', color: '#8b0000' },
    { id: 'escape', name: 'Escape Guide', color: '#28a745' }
  ];

  const currentPhaseIndex = phases.findIndex(phase => phase.id === currentPhase);

  // --- Drag and Drop State ---
  const [position, setPosition] = useState({ top: 20, left: window.innerWidth - 340 });
  const [dragging, setDragging] = useState(false);
  const [collapsed, setCollapsed] = useState(false);
  const dragOffset = useRef({ x: 0, y: 0 });

  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement> | React.TouchEvent<HTMLDivElement>) => {
    setDragging(true);
    let clientX: number, clientY: number;
    if ('touches' in e && e.touches.length > 0) {
      clientX = e.touches[0].clientX;
      clientY = e.touches[0].clientY;
    } else if ('clientX' in e) {
      clientX = e.clientX;
      clientY = e.clientY;
    } else {
      return;
    }
    dragOffset.current = {
      x: clientX - position.left,
      y: clientY - position.top
    };
    document.body.style.userSelect = 'none';
  };

  React.useEffect(() => {
    const handleMouseMove = (e: MouseEvent | TouchEvent) => {
      if (!dragging) return;
      let clientX: number, clientY: number;
      if ('touches' in e && (e as TouchEvent).touches.length > 0) {
        clientX = (e as TouchEvent).touches[0].clientX;
        clientY = (e as TouchEvent).touches[0].clientY;
      } else if ('clientX' in e) {
        clientX = (e as MouseEvent).clientX;
        clientY = (e as MouseEvent).clientY;
      } else {
        return;
      }
      setPosition(pos => ({
        top: Math.max(0, Math.min(window.innerHeight - 80, clientY - dragOffset.current.y)),
        left: Math.max(0, Math.min(window.innerWidth - 320, clientX - dragOffset.current.x))
      }));
    };
    const handleMouseUp = () => {
      setDragging(false);
      document.body.style.userSelect = '';
    };

    // Handle window resize to keep controls in viewport
    const handleResize = () => {
      setPosition(pos => ({
        top: Math.max(0, Math.min(window.innerHeight - 80, pos.top)),
        left: Math.max(0, Math.min(window.innerWidth - 320, pos.left))
      }));
    };

    if (dragging) {
      window.addEventListener('mousemove', handleMouseMove);
      window.addEventListener('touchmove', handleMouseMove);
      window.addEventListener('mouseup', handleMouseUp);
      window.addEventListener('touchend', handleMouseUp);
    }

    // Add resize listener
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('touchmove', handleMouseMove);
      window.removeEventListener('mouseup', handleMouseUp);
      window.removeEventListener('touchend', handleMouseUp);
      window.removeEventListener('resize', handleResize);
    };
  }, [dragging]);

  return (
    <div 
      className="simulation-controls"
      style={{
        position: 'fixed',
        top: position.top,
        left: position.left,
        background: 'rgba(255, 255, 255, 0.95)',
        border: '3px solid #007bff',
        borderRadius: '12px',
        padding: collapsed ? '0.5rem' : '1.5rem',
        zIndex: 30000,
        boxShadow: '0 8px 32px rgba(0,0,0,0.3)',
        backdropFilter: 'blur(10px)',
        minWidth: '300px',
        maxWidth: '400px',
        cursor: dragging ? 'grabbing' : 'default',
        userSelect: dragging ? 'none' : 'auto',
        transition: dragging ? 'none' : 'box-shadow 0.2s',
      }}

    >
      <div 
        style={{ 
          textAlign: 'center', 
          marginBottom: collapsed ? '0' : '1rem',
          borderBottom: collapsed ? 'none' : '2px solid #007bff',
          paddingBottom: collapsed ? '0' : '0.5rem',
          cursor: 'grab',
          userSelect: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between'
        }}
        onMouseDown={handleMouseDown}
        onTouchStart={handleMouseDown}
      >
        <div style={{ flex: 1 }}>
          <h3 style={{ 
            margin: 0, 
            color: '#007bff', 
            fontSize: '1.2rem',
            fontWeight: 'bold',
            pointerEvents: 'none'
          }}>
            🎮 Simulation Controls
          </h3>
          {!collapsed && (
            <div style={{ 
              fontSize: '0.9rem', 
              color: '#666',
              marginTop: '0.25rem',
              pointerEvents: 'none'
            }}>
              Protected from browser hijacking
            </div>
          )}
        </div>
        <button
          onClick={(e) => {
            e.stopPropagation();
            setCollapsed(!collapsed);
          }}
          style={{
            background: 'none',
            border: 'none',
            fontSize: '1.5rem',
            cursor: 'pointer',
            color: '#007bff',
            padding: '0.25rem',
            borderRadius: '4px',
            transition: 'background-color 0.2s',
            marginLeft: '0.5rem'
          }}
          onMouseEnter={(e) => {
            e.currentTarget.style.backgroundColor = 'rgba(0, 123, 255, 0.1)';
          }}
          onMouseLeave={(e) => {
            e.currentTarget.style.backgroundColor = 'transparent';
          }}
          title={collapsed ? 'Expand Controls' : 'Collapse Controls'}
        >
          {collapsed ? '▶' : '▼'}
        </button>
      </div>

      {!collapsed && (
        <>
          <div style={{ marginBottom: '1rem' }}>
        <div style={{ 
          fontSize: '0.9rem', 
          fontWeight: 'bold', 
          marginBottom: '0.5rem',
          color: '#333'
        }}>
          Current Phase: {phases[currentPhaseIndex]?.name}
        </div>
        <div style={{ 
          display: 'flex', 
          gap: '0.25rem',
          flexWrap: 'wrap'
        }}>
          {phases.map((phase, index) => (
            <div
              key={phase.id}
              style={{
                width: '20px',
                height: '20px',
                borderRadius: '50%',
                backgroundColor: phase.id === currentPhase ? phase.color : '#e9ecef',
                border: phase.id === currentPhase ? '2px solid #333' : '1px solid #ccc',
                cursor: 'pointer',
                transition: 'all 0.2s ease',
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'center',
                fontSize: '0.6rem',
                color: phase.id === currentPhase ? 'white' : '#666',
                fontWeight: 'bold'
              }}
              onClick={() => onAdvancePhase(phase.id as any)}
              title={`${phase.name} (${index + 1}/${phases.length})`}
            >
              {index + 1}
            </div>
          ))}
        </div>
      </div>

      <div style={{ 
        display: 'flex', 
        gap: '0.5rem',
        flexWrap: 'wrap'
      }}>
        <button
          onClick={() => {
            const nextIndex = (currentPhaseIndex + 1) % phases.length;
            onAdvancePhase(phases[nextIndex].id as any);
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#007bff',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px'
          }}
        >
          Next →
        </button>

        <button
          onClick={() => {
            const prevIndex = currentPhaseIndex === 0 ? phases.length - 1 : currentPhaseIndex - 1;
            onAdvancePhase(phases[prevIndex].id as any);
          }}
          style={{
            padding: '0.5rem 1rem',
            background: '#6c757d',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1,
            minWidth: '80px'
          }}
        >
          ← Previous
        </button>
      </div>

      <div style={{ 
        display: 'flex', 
        gap: '0.5rem',
        marginTop: '0.5rem'
      }}>
        <button
          onClick={onLearnMore}
          style={{
            padding: '0.5rem 1rem',
            background: '#28a745',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1
          }}
        >
          📚 Learn More
        </button>

        <button
          onClick={onReset}
          style={{
            padding: '0.5rem 1rem',
            background: '#dc3545',
            color: 'white',
            border: 'none',
            borderRadius: '6px',
            cursor: 'pointer',
            fontSize: '0.9rem',
            fontWeight: 'bold',
            flex: 1
          }}
        >
          🔄 Reset
        </button>
      </div>



      {/* Norton phase control switches */}
      {currentPhase === 'norton' && (
        <div style={{ 
          marginTop: '0.5rem'
        }}>
          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'space-between',
            marginBottom: '0.5rem',
            padding: '0.5rem',
            background: 'rgba(220, 53, 69, 0.1)',
            borderRadius: '6px',
            border: '1px solid rgba(220, 53, 69, 0.2)'
          }}>
            <div style={{ fontSize: '0.9rem', fontWeight: 'bold', color: '#dc3545' }}>
              ⚡ Escalation Mode
            </div>
            <div
              onClick={() => {
                console.log('⏭️ Toggle Escalation switch clicked');
                if ((window as any).toggleNortonEscalation) {
                  (window as any).toggleNortonEscalation();
                } else {
                  console.log('⚠️ Toggle escalation function not available');
                }
              }}
              style={{
                width: '50px',
                height: '24px',
                background: nortonEscalation ? '#dc3545' : '#6c757d',
                borderRadius: '12px',
                cursor: 'pointer',
                position: 'relative',
                transition: 'background-color 0.3s ease',
                border: '2px solid #fff',
                boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
              }}
            >
              <div style={{
                width: '18px',
                height: '18px',
                background: '#fff',
                borderRadius: '50%',
                position: 'absolute',
                top: '1px',
                left: nortonEscalation ? '27px' : '1px',
                transition: 'left 0.3s ease',
                boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
              }} />
            </div>
          </div>

          <div style={{ 
            display: 'flex', 
            alignItems: 'center', 
            justifyContent: 'space-between',
            padding: '0.5rem',
            background: 'rgba(108, 117, 125, 0.1)',
            borderRadius: '6px',
            border: '1px solid rgba(108, 117, 125, 0.2)'
          }}>
            <div style={{ fontSize: '0.9rem', fontWeight: 'bold', color: '#6c757d' }}>
              🔊 Speech
            </div>
            <div
              onClick={() => {
                console.log('🔇 Toggle Speech switch clicked');
                if ((window as any).toggleNortonSpeech) {
                  (window as any).toggleNortonSpeech();
                } else {
                  console.log('⚠️ Toggle speech function not available');
                }
              }}
              style={{
                width: '50px',
                height: '24px',
                background: nortonMuted ? '#6c757d' : '#28a745',
                borderRadius: '12px',
                cursor: 'pointer',
                position: 'relative',
                transition: 'background-color 0.3s ease',
                border: '2px solid #fff',
                boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
              }}
            >
              <div style={{
                width: '18px',
                height: '18px',
                background: '#fff',
                borderRadius: '50%',
                position: 'absolute',
                top: '1px',
                left: nortonMuted ? '1px' : '27px',
                transition: 'left 0.3s ease',
                boxShadow: '0 1px 3px rgba(0,0,0,0.3)'
              }} />
            </div>
          </div>
        </div>
      )}

      <div style={{ 
        marginTop: '1rem',
        padding: '0.75rem',
        background: 'rgba(0, 123, 255, 0.1)',
        borderRadius: '6px',
        border: '1px solid rgba(0, 123, 255, 0.2)',
        fontSize: '0.8rem',
        color: '#0056b3'
      }}>
        <strong>💡 Tip:</strong> Click any scareware button to see educational popups about why you should never click them in real life!
      </div>
        </>
      )}
    </div>
  );
};

export default SimulationControls;
